import React, { useState } from "react";
import { connectWallet } from "../utils/blockchain";
import { ethers } from "ethers";

export default function SetLimits() {
  const [tokenId, setTokenId] = useState("");
  const [newPriceCap, setNewPriceCap] = useState("");
  const [newExpiration, setNewExpiration] = useState("");
  const [message, setMessage] = useState("");

  const handleSetLimits = async () => {
    try {
      setMessage("Updating limits...");
      const { contract } = await connectWallet();

      const priceCapWei = ethers.utils.parseEther(newPriceCap);
      const expirationTimestamp = Math.floor(new Date(newExpiration).getTime() / 1000);

      // Misal fungsi smart contract: setResalePriceCap(tokenId, priceCap), setExpiration(tokenId, expiration)
      let tx = await contract.setResalePriceCap(tokenId, priceCapWei);
      await tx.wait();

      tx = await contract.setExpiration(tokenId, expirationTimestamp);
      await tx.wait();

      setMessage("Limits updated successfully!");
    } catch (error) {
      setMessage("Error: " + error.message);
    }
  };

  return (
    <div style={{ margin: "20px 0" }}>
      <h2>Set Resale Price Cap & Expiration Date</h2>
      <input
        type="number"
        placeholder="Token ID"
        value={tokenId}
        onChange={(e) => setTokenId(e.target.value)}
        style={{ width: "100px", marginRight: "10px" }}
      />
      <input
        type="text"
        placeholder="New Resale Price Cap (ETH)"
        value={newPriceCap}
        onChange={(e) => setNewPriceCap(e.target.value)}
        style={{ width: "180px", marginRight: "10px" }}
      />
      <input
        type="date"
        value={newExpiration}
        onChange={(e) => setNewExpiration(e.target.value)}
        style={{ marginRight: "10px" }}
      />
      <button onClick={handleSetLimits}>Set Limits</button>
      <p>{message}</p>
    </div>
  );
}
